export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

// In-memory store standing in for a real database.
const store = globalThis as unknown as { __posts?: Post[] }
store.__posts ??= []

export async function getPosts(): Promise<Post[]> {
  // Newest first
  return [...store.__posts!].reverse()
}

export async function insertPost(
  title: string,
  content: string
): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }
  store.__posts!.push(post)
  return post
}

