'use server'

import { updateTag } from 'next/cache'
import { insertPost } from './lib/posts'

export async function createPost(formData: FormData) {
  const title = formData.get('title')
  const content = formData.get('content')

  if (typeof title !== 'string' || title.trim() === '') {
    throw new Error('Title is required')
  }
  if (typeof content !== 'string' || content.trim() === '') {
    throw new Error('Content is required')
  }

  await insertPost(title.trim(), content.trim())

  // updateTag expires the "posts" cache entries immediately: the next read
  // blocks until fresh data is fetched (read-your-own-writes). revalidateTag
  // would instead serve the stale entry once while refreshing in the
  // background, which must not happen here.
  updateTag('posts')
}

